class PunchOutCartMessageBuilder:
    def __init__(self):
        pass

    def build_punchout_message(self, buyer_cookie: str, cart_items: list) -> dict:
        total_net = sum(item["unit_price"] * item["qty"] for item in cart_items)
        items_count = sum(item["qty"] for item in cart_items)
        return {
            "cxml_message_type": "PunchOutOrderMessage",
            "buyer_cookie": buyer_cookie,
            "total_items_count": items_count,
            "total_net_amount_usd": round(total_net, 2),
            "currency": "USD",
            "cxml_conformance": "CXML_V1_2_COMPLIANT"
        }

cart_builder = PunchOutCartMessageBuilder()
items = [
    {"sku": "SKU_SERVER_RACK", "unit_price": 3240.0, "qty": 2},
    {"sku": "SKU_NETWORK_SWITCH", "unit_price": 864.0, "qty": 4}
]
cxml_res = cart_builder.build_punchout_message("COOKIE-99881234", items)
print(f"cXML Message: Type: {cxml_res['cxml_message_type']} | Cookie: {cxml_res['buyer_cookie']} | Items: {cxml_res['total_items_count']} | Total: ${cxml_res['total_net_amount_usd']:,.2f} | Status: {cxml_res['cxml_conformance']}")

