class OCICartFormatter:
    def __init__(self):
        pass

    def format_oci_fields(self, items: list) -> dict:
        oci_post_params = {}
        for idx, item in enumerate(items, start=1):
            oci_post_params[f"NEW_ITEM-DESCRIPTION[{idx}]"] = item["desc"]
            oci_post_params[f"NEW_ITEM-QUANTITY[{idx}]"] = str(item["qty"])
            oci_post_params[f"NEW_ITEM-PRICE[{idx}]"] = f"{item['price']:.2f}"
            oci_post_params[f"NEW_ITEM-CURRENCY[{idx}]"] = "USD"
            oci_post_params[f"NEW_ITEM-UNIT[{idx}]"] = "EA"

        return {
            "protocol": "SAP_OCI_ROUNDTRIP_V4",
            "total_line_items": len(items),
            "oci_param_count": len(oci_post_params),
            "first_item_desc": oci_post_params["NEW_ITEM-DESCRIPTION[1]"],
            "first_item_price": oci_post_params["NEW_ITEM-PRICE[1]"]
        }

oci_formatter = OCICartFormatter()
oci_items = [
    {"desc": "Enterprise 42U Server Rack", "qty": 2, "price": 3240.00},
    {"desc": "Managed 48-Port Switch", "qty": 4, "price": 864.00}
]
oci_res = oci_formatter.format_oci_fields(oci_items)
print(f"OCI Format: Protocol: {oci_res['protocol']} | Lines: {oci_res['total_line_items']} | Params: {oci_res['oci_param_count']} | Item 1: {oci_res['first_item_desc']} @ ${oci_res['first_item_price']}")
